await story('A8-10-control-after-link-refresh',async()=>{await waitFor(()=>online,'independent manual reconnects after revocation',20000);check('manual credential remains paired',api.view().state==='paired');await globalThis.a8Manual.m.p.reload();await globalThis.a8Manual.m.p.locator('[data-fleet-status=active]').waitFor();await shot(globalThis.a8Manual.m.p,'A8-10-control-fleet-active');receipt.finalStates={manualProfile:api.view().state,manualOnline:online,holds:receipt.holds};});
